// DIP = principe d'inversion des dependances : dependre d'une abstraction, pas d'un detail concret.

// Couple a une implementation concrete (couplage fort)
class OrderService {
    private final PostgresRepo repo = new PostgresRepo(); // atele a Postgres
}

// Decouple : depend d'un PORT (une interface = un contrat), pas d'un detail
class OrderService {
    private final OrderRepository repo; // interface : le "quoi", pas le "comment"
    OrderService(OrderRepository repo) { // on injecte l'implementation par le constructeur
        this.repo = repo;
    }
}

// Connascence de position : l'appelant doit connaître l'ORDRE exact
new Reservation("2026-07-21", "2026-07-25", 2, true, false);
// 2 quoi ? true/false = quoi ? l'ordre est un couplage fragile

// Reduit en connascence de nom (plus faible) : un builder / des parametres nommes
Reservation.builder()
    .checkIn(LocalDate.parse("2026-07-21"))
    .checkOut(LocalDate.parse("2026-07-25"))
    .guests(2)
    .breakfast(true)
    .nonRefundable(false)
    .build();
// L'ordre n'a plus d'importance ; on s'accorde sur des NOMS, pas des positions
